-- Initial Lala Jagannath CMS schema. Run once on a new Supabase project.
create extension if not exists pgcrypto;
create table if not exists public.admin_members (user_id uuid primary key references auth.users(id) on delete cascade, role text not null default 'admin' check (role in ('owner','admin','editor')), created_at timestamptz not null default now());
create table if not exists public.site_sections (id uuid primary key default gen_random_uuid(), section_key text not null unique, title_en text not null, title_hi text not null, subtitle_en text, body_en text, image_url text, display_order integer not null default 0, is_published boolean not null default false, updated_at timestamptz not null default now(), created_at timestamptz not null default now());
create table if not exists public.site_settings (id uuid primary key default gen_random_uuid(), setting_key text not null unique, value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.doctors (id uuid primary key default gen_random_uuid(), name text not null, title text, bio_en text, bio_hi text, image_url text, display_order integer not null default 0, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.services (id uuid primary key default gen_random_uuid(), title_en text not null, title_hi text, description_en text, description_hi text, image_url text, display_order integer not null default 0, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.yoga_tutorials (id uuid primary key default gen_random_uuid(), name text not null, sanskrit_name text, description_en text, description_hi text, steps jsonb not null default '[]'::jsonb, breathing_guidance text, benefits text, precautions text, media_url text, duration_minutes integer, slug text unique, seo_title text, seo_description text, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.articles (id uuid primary key default gen_random_uuid(), title text not null, slug text unique, excerpt text, body text, image_url text, seo_title text, seo_description text, is_published boolean not null default false, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.testimonials (id uuid primary key default gen_random_uuid(), display_name text not null, quote text not null, language text default 'en', display_order integer not null default 0, is_published boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.faqs (id uuid primary key default gen_random_uuid(), question_en text not null, question_hi text, answer_en text not null, answer_hi text, display_order integer not null default 0, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.appointment_requests (id uuid primary key default gen_random_uuid(), name text not null, phone text not null, email text, requested_date date, message text, status text not null default 'new' check (status in ('new','contacted','closed')), created_at timestamptz not null default now());
create table if not exists public.contact_messages (id uuid primary key default gen_random_uuid(), name text not null, email text not null, subject text, message text not null, status text not null default 'new' check (status in ('new','read','closed')), created_at timestamptz not null default now());
create index if not exists site_sections_published_order_idx on public.site_sections(is_published,display_order);
create index if not exists services_published_order_idx on public.services(is_published,display_order);
create index if not exists doctors_published_order_idx on public.doctors(is_published,display_order);
create index if not exists articles_published_idx on public.articles(is_published,published_at desc);
alter table public.admin_members enable row level security;
alter table public.site_sections enable row level security;
alter table public.site_settings enable row level security;
alter table public.doctors enable row level security;
alter table public.services enable row level security;
alter table public.yoga_tutorials enable row level security;
alter table public.articles enable row level security;
alter table public.testimonials enable row level security;
alter table public.faqs enable row level security;
alter table public.appointment_requests enable row level security;
alter table public.contact_messages enable row level security;
drop policy if exists "admins can view own membership" on public.admin_members;
create policy "admins can view own membership" on public.admin_members for select to authenticated using (user_id=auth.uid());
drop policy if exists "public reads published site_sections" on public.site_sections;
create policy "public reads published site_sections" on public.site_sections for select to anon,authenticated using (is_published=true);
drop policy if exists "public reads published site_settings" on public.site_settings;
create policy "public reads published site_settings" on public.site_settings for select to anon,authenticated using (setting_key not like 'private.%');
drop policy if exists "public reads published doctors" on public.doctors;
create policy "public reads published doctors" on public.doctors for select to anon,authenticated using (is_published=true);
drop policy if exists "public reads published services" on public.services;
create policy "public reads published services" on public.services for select to anon,authenticated using (is_published=true);
drop policy if exists "public reads published yoga_tutorials" on public.yoga_tutorials;
create policy "public reads published yoga_tutorials" on public.yoga_tutorials for select to anon,authenticated using (is_published=true);
drop policy if exists "public reads published articles" on public.articles;
create policy "public reads published articles" on public.articles for select to anon,authenticated using (is_published=true);
drop policy if exists "public reads published testimonials" on public.testimonials;
create policy "public reads published testimonials" on public.testimonials for select to anon,authenticated using (is_published=true);
drop policy if exists "public reads published faqs" on public.faqs;
create policy "public reads published faqs" on public.faqs for select to anon,authenticated using (is_published=true);
do $$ declare t text; begin foreach t in array array['site_sections','site_settings','doctors','services','yoga_tutorials','articles','testimonials','faqs'] loop execute format('drop policy if exists %I on public.%I','admins manage '||t,t); execute format('create policy %I on public.%I for all to authenticated using (exists (select 1 from public.admin_members m where m.user_id=auth.uid() and m.role in (''owner'',''admin'',''editor''))) with check (exists (select 1 from public.admin_members m where m.user_id=auth.uid() and m.role in (''owner'',''admin'',''editor'')))','admins manage '||t,t); end loop; end $$;
drop policy if exists "admins manage appointment_requests" on public.appointment_requests;
create policy "admins manage appointment_requests" on public.appointment_requests for all to authenticated using (exists(select 1 from public.admin_members m where m.user_id=auth.uid() and m.role in ('owner','admin'))) with check (exists(select 1 from public.admin_members m where m.user_id=auth.uid() and m.role in ('owner','admin')));
drop policy if exists "admins manage contact_messages" on public.contact_messages;
create policy "admins manage contact_messages" on public.contact_messages for all to authenticated using (exists(select 1 from public.admin_members m where m.user_id=auth.uid() and m.role in ('owner','admin'))) with check (exists(select 1 from public.admin_members m where m.user_id=auth.uid() and m.role in ('owner','admin')));
drop policy if exists "public submits appointment requests" on public.appointment_requests;
create policy "public submits appointment requests" on public.appointment_requests for insert to anon,authenticated with check (length(trim(name)) between 2 and 120 and length(trim(phone)) between 7 and 30 and (email is null or length(email)<=254) and (message is null or length(message)<=3000));
drop policy if exists "public submits contact messages" on public.contact_messages;
create policy "public submits contact messages" on public.contact_messages for insert to anon,authenticated with check (length(trim(name)) between 2 and 120 and length(trim(email)) between 3 and 254 and length(trim(message)) between 1 and 5000);
insert into public.site_sections(section_key,title_en,title_hi,display_order,is_published) values ('hero','Welcome to Lala Jagannath','लाला जगन्नाथ में आपका स्वागत है',1,true),('about','About our centre','हमारे केंद्र के बारे में',2,true),('doctors','Our doctors','हमारे चिकित्सक',3,true),('services','Our therapies','हमारी चिकित्सा',4,true),('conditions','Conditions we support','स्वास्थ्य समस्याएँ',5,true),('mind-healing','Mind healing','मन की चिकित्सा',6,true),('virtual-havan','Virtual havan','वर्चुअल हवन',7,true),('philosophy','Our philosophy','हमारा दर्शन',8,true),('ladies-wellness','Ladies wellness','महिला स्वास्थ्य',9,true),('testimonials','Patient stories','अनुभव',10,true),('faq','Frequently asked questions','अक्सर पूछे जाने वाले प्रश्न',11,true),('contact','Contact us','संपर्क करें',12,true) on conflict(section_key) do nothing;

